import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
sess_cols = {}
for t in tables:
    cols = [c[1] for c in con.execute(f'PRAGMA table_info("{t}")')]
    s = [c for c in cols if c.endswith('_session') or c == 'session' or c == 'session_id']
    if s: sess_cols[t] = s
# all distinct session values across session-bearing tables
vals = set()
for t, cols in sess_cols.items():
    for c in cols:
        for (v,) in con.execute(f'select distinct "{c}" from "{t}" where "{c}" is not null'):
            vals.add(v)
print("distinct session values (all session cols):", len(vals))
# most recent three: session_YYYY-MM-DD-<slug> sorts by date prefix; report lexical top 3 and check format
import re
fmt_ok = [v for v in vals if re.match(r'^session_\d{4}-\d{2}-\d{2}-', v)]
print("values matching session_YYYY-MM-DD-*:", len(fmt_ok), "of", len(vals))
top3 = sorted(fmt_ok, reverse=True)[:3]
print("three most recent (by date stem):", top3)
for s in top3:
    print("==", s)
    for t, cols in sess_cols.items():
        for c in cols:
            n = con.execute(f'select count(*) from "{t}" where "{c}"=?', (s,)).fetchone()[0]
            if n: print(f"   {n:>6}  {t}.{c}")
PY

