import sqlite3, re
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
vals = {}
for t in tables:
    cols = [c[1] for c in con.execute(f'PRAGMA table_info("{t}")')]
    for c in cols:
        if c.endswith('_session') or c in ('session','session_id'):
            for (v,) in con.execute(f'select distinct "{c}" from "{t}" where "{c}" is not null'):
                vals.setdefault(v, set()).add(f"{t}.{c}")
bad = sorted(v for v in vals if not re.match(r'^session_\d{4}-\d{2}-\d{2}-', v))
print("non-matching session values:", len(bad))
for v in bad: print("  ", repr(v), sorted(vals[v]))
dated = [(re.search(r'\d{4}-\d{2}-\d{2}', v).group(0), v) for v in vals if re.search(r'\d{4}-\d{2}-\d{2}', v)]
dated.sort(reverse=True)
print("three most recent by embedded date (all values):")
for d, v in dated[:3]: print("  ", d, v)
